  const { removeRetiredIndexFiles } = await import('../engine/converge-wiring.mjs');
  const root = mkRepo();
  mkdirSync(join(root, '.claudinite', 'flat'), { recursive: true });
  writeFileSync(join(root, OLD_RULES_INDEX), 'old\n');
