    // never fingerprinted, so its lines say nothing; the manifest spec tolerates them
    // only until no member still carries them.
    for (const path of (ctx.files ?? []).filter((f) => LOCAL_MANIFEST.test(f))) {
      const text = ctx.read(path) ?? '';
