});

input.new_string:
  const dashboards = JSON.parse(readFileSync(join(root, '.claudinite', 'flat', 'dashboard.GENERATED.json'), 'utf8'));
  assert.deepEqual(dashboards.dashboards.basics.declaration, { widgets: [] }); // @real-entity as above
});

// A member still holding files the layout left behind keeps them as they are: the
// converge writes the flat directory beside them and deletes nothing it did not write.
test('convergeWiring: leaves a member\'s files at the paths the layout left untouched', async () => {
  const root = mkRepo();
  mkdirSync(join(root, '.claudinite', 'local'), { recursive: true });
  writeFileSync(join(root, '.claudinite-settings.json'), '{ "packs": [] }\n');
  const left = {
    '.claudinite/claudinite-rules.GENERATED.md': 'old rules\n',
    '.claudinite/local/usage.GENERATED.json': '{"history":[1]}\n',
  };
  for (const [path, text] of Object.entries(left)) writeFileSync(join(root, path), text);

  await convergeWiring(root, REPO);

  for (const [path, text] of Object.entries(left)) assert.equal(readFileSync(join(root, path), 'utf8'), text, path);
  assert.ok(existsSync(join(root, RULES_INDEX_FILE)), 'the flat index is written beside them');
});

