// Every declared pack the member's flat descriptor file names, with its values.
//
// What it spends is one CONTENT read for every descriptor, plus one values read per
// contributing pack — all at a sha, therefore cached forever and free while the branch
// has not moved — plus, if any widget asks for one, the live sources the caller passes
// in.
//
  // day on which nothing ran must still open nothing.
  if (landed !== null && withoutStamp(landed) === withoutStamp(text)) {
    return { files: {}, summary: `${summary} — byte-identical` };
  }

